const stages=[{k:'HYPATIA + HYPERIA',t:'Discover what is true—and what is still unknown.',c:'Rank hypotheses, synthesize sources, and label every consequential claim as Observed, Derived, Assumed, or Unknown.',l:['Evidence ledger','Competing explanations','Discriminating measurement plan']},{k:'INTELLIGENT ENGINEER',t:'Convert validated knowledge into verifiable options.',c:'Preserve requirements, interfaces, assumptions, failure modes, and configuration state while evaluating alternatives.',l:['Trade study','Interface model','Verification matrix']},{k:'GROUND-TRUTH GATEKEEPER',t:'Test the work before the work moves on.',c:'Recompute critical values, inspect provenance, execute acceptance tests, and block unsupported promotion.',l:['Pass / conditional pass / fail','Independent checks','Exact remediation']},{k:'PM ACCELERATOR + VIBE ENGINEERING',t:'Deliver owned, reproducible work.',c:'Turn approved decisions into executable packages with clear owners, rollback, and closure evidence.',l:['Owned milestones','Reproducible release','Approval record']},{k:'MISSION MEMORY STEWARD',t:'Make outcomes improve the next process.',c:'Record validated facts and decisions, measure results, and version approved playbook changes without rewriting history.',l:['Durable state','Outcome review','Versioned evolution']}];document.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-stage]').forEach(x=>x.setAttribute('aria-selected','false'));b.setAttribute('aria-selected','true');let s=stages[+b.dataset.stage];stageKicker.textContent=s.k;stageTitle.textContent=s.t;stageCopy.textContent=s.c;stageList.innerHTML=s.l.map(x=>`<li>${x}</li>`).join('')}));document.getElementById('filter').addEventListener('input',e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('.download-list li').forEach(li=>li.hidden=!li.textContent.toLowerCase().includes(q))});
const updateStyles=document.createElement('link');updateStyles.rel='stylesheet';updateStyles.href='updates.css';document.head.appendChild(updateStyles);
const skillDepth={
 'Hypatia Science Harness':'Ten research phases plus evidence reports, hypothesis diagrams, study workflows, analysis charts, uncertainty visuals, peer-review matrices, and an approved Engineering Evidence Package.',
 'Intelligent Engineer Harness':'Ten phase-locked workspaces plus ConOps, requirements, trade, design, FMEA, verification, configuration, and release reports with controlled engineering visuals.',
 'Pm Accelerator Harness':'Nine project phases with Plan, Execute, and Change loops plus WBS, Gantt, network, resource, cost, risk, status, change-impact, and closure reports and dashboards.'
};
document.querySelectorAll('.skill-card').forEach(card=>{const h=card.querySelector('h3');if(h&&skillDepth[h.textContent])card.querySelector('p').textContent=skillDepth[h.textContent]});
const downloads=document.querySelector('.download-list');if(downloads){const item=document.createElement('li');item.dataset.kind='json memory wiki';item.innerHTML='<span><b>Wiki-Style Project Memory Starter</b><small>Validated JSON knowledge graph for claims, sources, requirements, configurations, WBS, decisions, risks, artifacts, and revision history</small></span><a href="downloads/Mars_Harness_Project_Wiki_Memory_Starter.json" download>Download</a>';downloads.insertBefore(item,downloads.firstChild)}
if(downloads){const model=document.createElement('li');model.dataset.kind='agents architecture';model.innerHTML='<span><b>Recursive Specialized Agent Operating Model</b><small>Science, Engineering, and Project Management leads, 31 core specialists, cross-domain controls, and recursive spawning rules</small></span><a href="downloads/markdown/19_Recursive_Specialized_Agent_Operating_Model.md" target="_blank">Open</a>';downloads.insertBefore(model,downloads.firstChild);const manifest=document.createElement('li');manifest.dataset.kind='agents json manifest';manifest.innerHTML='<span><b>Recursive Agent Manifest</b><small>Machine-readable hierarchy, delegation limits, task-packet fields, and output contracts</small></span><a href="downloads/Mars_Harness_Recursive_Agent_Manifest.json" download>Download</a>';downloads.insertBefore(manifest,downloads.firstChild)}
